function check(input, actual, expected) {
  const [values] = input;
  if (!Array.isArray(actual)) return false;
  if (actual.length === 0) return values.length === 0;
  if (typeof actual[0] !== 'number') return false;
  // Rebuild the tree from its level-order form; nodes ends up in breadth-first order.
  const nodes = [{ val: actual[0], left: null, right: null }];
  let i = 1;
  for (let q = 0; q < nodes.length && i < actual.length; q++) {
    for (const side of ['left', 'right']) {
      if (i < actual.length && actual[i] !== null) {
        if (typeof actual[i] !== 'number') return false;
        const node = { val: actual[i], left: null, right: null };
        nodes[q][side] = node;
        nodes.push(node);
      }
      i++;
    }
  }
  if (i < actual.length || nodes.length !== values.length) return false;
  // The in-order traversal must reproduce the list.
  const stack = [];
  let current = nodes[0], index = 0;
  while (current || stack.length) {
    while (current) { stack.push(current); current = current.left; }
    current = stack.pop();
    if (current.val !== values[index++]) return false;
    current = current.right;
  }
  // Children come after their parents in breadth-first order, so walk backwards to get heights.
  const height = new Map();
  for (let k = nodes.length - 1; k >= 0; k--) {
    const left = nodes[k].left ? height.get(nodes[k].left) : 0;
    const right = nodes[k].right ? height.get(nodes[k].right) : 0;
    if (Math.abs(left - right) > 1) return false;
    height.set(nodes[k], 1 + Math.max(left, right));
  }
  return true;
}

validator:
function validate([head]) {
  if (!Array.isArray(head)) return 'head must be a list of numbers.';
  if (head.length > 20000) return 'The list has at most 20000 nodes.';
  for (let i = 0; i < head.length; i++) {
    if (!Number.isInteger(head[i]) || head[i] < -100000 || head[i] > 100000) return 'Each value is an integer between -100000 and 100000.';
    if (i > 0 && head[i] < head[i - 1]) return 'The values must be sorted in non-decreasing order.';
  }
  return null;
}

