function sortedListToBST(head) {
  const build = (start, end) => {
    if (start === end) {
      return null;
    }
    let slow = start;
    let fast = start;
    while (fast !== end && fast.next !== end) {
      slow = slow.next;
      fast = fast.next.next;
    }
    const root = new TreeNode(slow.val);
    root.left = build(start, slow);
    root.right = build(slow.next, end);
    return root;
  };
  return build(head, null);
}

