function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : Math.floor(rand() * 11);
  const maxStep = size === 'large' ? 99 : 4;
  const values = [];
  let value = size === 'large' ? -100000 + Math.floor(rand() * 1000) : Math.floor(rand() * 21) - 10;
  for (let i = 0; i < n; i++) {
    values.push(value);
    // Mostly increasing, with an occasional repeated value.
    value += rand() < 0.15 ? 0 : 1 + Math.floor(rand() * maxStep);
  }
  return [values];
}
